import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        java.util.List<String> stdin = new java.util.ArrayList<>();
        while (scanner.hasNextLine()) {
            stdin.add(scanner.nextLine());
        }
        main(stdin);
    }

    public static void main(java.util.List<String> stdin) {
        int m = Integer.parseInt(stdin.get(0));
        long n = 1;
        for (int i = 1; i <= m; i++) {
            n += 4 * (i - 1);
        }
        System.out.println(n);
    }
}
